@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Material — Material Design 3: tonal palette, filled surfaces, elevation */
.theme-material {
  --bg: oklch(0.97 0.012 300);
  --surface: oklch(0.985 0.008 300);
  --surface-2: oklch(0.93 0.03 295);
  --fg: oklch(0.22 0.02 300);
  --fg-muted: oklch(0.47 0.025 300);
  --accent: oklch(0.5 0.19 295);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.55 0.14 200);
  --line: oklch(0.76 0.02 300);
  --success: oklch(0.58 0.14 152);
  --warning: oklch(0.72 0.14 78);
  --danger: oklch(0.52 0.2 27);

  --radius: 1rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px 0 oklch(0.2 0.02 300 / 30%), 0 1px 3px 1px oklch(0.2 0.02 300 / 15%);
  --shadow-2: 0 1px 2px 0 oklch(0.2 0.02 300 / 30%), 0 2px 6px 2px oklch(0.2 0.02 300 / 15%);
  --shadow-3: 0 4px 4px 0 oklch(0.2 0.02 300 / 30%), 0 8px 12px 6px oklch(0.2 0.02 300 / 15%);
  --glow: 0 0 0 4px oklch(0.5 0.19 295 / 14%);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Roboto Flex", "Roboto", sans-serif;
  --font-body: "Roboto Flex", "Roboto", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.06em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-material h1,
.theme-material h2,
.theme-material h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-display);
}

/* M3 state layer: hovering a control tints it with the accent at low opacity. */
.theme-material button:hover,
.theme-material a:hover {
  position: relative;
}

.theme-material button:hover {
  background-image: linear-gradient(
    oklch(0.5 0.19 295 / 8%),
    oklch(0.5 0.19 295 / 8%)
  );
}

/* signature */
.theme-material { --font-ui: var(--font-display); }
.theme-material button { transition: box-shadow 200ms cubic-bezier(0.2, 0, 0, 1); }
.theme-material button:hover { box-shadow: 0 2px 8px oklch(0 0 0 / 25%); }
.theme-material h1 { font-weight: 500; }

/* depth */
.theme-material thead th { font-weight: 500; font-size: 0.8em; color: var(--fg-muted); border-bottom: 1px solid var(--line); text-align: left; }
.theme-material td { border-bottom: 1px solid oklch(0.76 0.02 300 / 40%); }
.theme-material tbody tr { transition: background 150ms cubic-bezier(0.2, 0, 0, 1); }
.theme-material tbody tr:hover { background: oklch(0.5 0.19 295 / 8%); }
/* physical: M3 filled text field — tonal fill, underline indicator that thickens on focus */
.theme-material input, .theme-material select, .theme-material textarea { background: var(--surface-2); border: 0; border-bottom: 1px solid var(--fg-muted); border-radius: var(--radius-sm) var(--radius-sm) 0 0; transition: border-color 150ms cubic-bezier(0.2, 0, 0, 1); }
.theme-material input:focus, .theme-material select:focus, .theme-material textarea:focus { outline: none; border-bottom: 2px solid var(--accent); box-shadow: none; }
.theme-material a { color: var(--accent); text-decoration: none; }
.theme-material a:hover { text-decoration: underline; text-underline-offset: 3px; }
.theme-material button:active { box-shadow: none; background-image: linear-gradient(oklch(0.5 0.19 295 / 12%), oklch(0.5 0.19 295 / 12%)); }
.theme-material kbd { font-family: var(--font-mono); font-size: 0.85em; padding: 0.1em 0.5em; background: var(--surface-2); border-radius: var(--radius-pill); border: 1px solid var(--line); }
.theme-material ::selection { background: oklch(0.5 0.19 295 / 25%); }
.theme-material ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-material ::-webkit-scrollbar-track { background: transparent; }
.theme-material ::-webkit-scrollbar-thumb { background: var(--line); border-radius: 9999px; }
.theme-material ::-webkit-scrollbar-thumb:hover { background: var(--fg-muted); }
.theme-material .label-caps { color: var(--accent); font-weight: 500; }
.theme-material .themed-border { border-left: 4px solid var(--accent); border-radius: var(--radius-sm); }

/* alt mode: M3 dark scheme — tonal surfaces, lightened primary (80-tone) */
.theme-material.alt-mode {
  --bg: oklch(0.145 0.012 300.0);
  --surface: oklch(0.185 0.012 300.0);
  --surface-2: oklch(0.225 0.012 300.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --accent: oklch(0.8 0.12 295);
  --accent-fg: oklch(0.28 0.1 295);
  --accent-2: oklch(0.78 0.1 200);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-material.alt-mode tbody tr:hover { background: oklch(0.8 0.12 295 / 10%); }
.theme-material.alt-mode button:hover { background-image: linear-gradient(oklch(0.8 0.12 295 / 8%), oklch(0.8 0.12 295 / 8%)); }
.theme-material.alt-mode button:active { background-image: linear-gradient(oklch(0.8 0.12 295 / 12%), oklch(0.8 0.12 295 / 12%)); }
.theme-material.alt-mode ::selection { background: oklch(0.8 0.12 295 / 30%); }
.theme-material.alt-mode td { border-bottom-color: oklch(1 0 0 / 10%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
